SELECT br.*, t.name as teacher_name, b.title as book_title, b.author as author, b.isbn, DATEDIFF(CURDATE(), br.due_date) as overdue_days FROM borrow_record br LEFT JOIN teacher t ON br.teacher_id = t.id LEFT JOIN book b ON br.book_id = b.id WHERE br.teacher_id = #{teacherId}
AND br.status = #{status}
ORDER BY br.borrow_date DESC

SELECT br.*, t.name as teacher_name, b.title as book_title, b.author as author, b.isbn
FROM borrow_record br
LEFT JOIN teacher t ON br.teacher_id = t.id
LEFT JOIN book b ON br.book_id = b.id


        AND t.name LIKE CONCAT('%', #{teacherName}, '%')


        AND b.title LIKE CONCAT('%', #{bookTitle}, '%')


        AND br.status = #{status}


        AND br.borrow_date  >=  #{startDate}


        AND br.borrow_date  <=  #{endDate}


ORDER BY br.borrow_date DESC

